file_lines = [
    '"""Khyber Pakhtunkhwa Mega Dataset for GoTourGo (140+ Curated Landmarks)."""',
    'from __future__ import annotations',
    'from scripts.landmark_builder.generator import make_clean_record',
    '',
    'KP_MEGA_DATA = ['
]

for t in KP_DATA:
    file_lines.append(f'    {repr(t)},')

file_lines.extend([
    ']',
    '',
    'def get_kp_mega() -> list[dict]:',
    '    records = []',
    '    for item in KP_MEGA_DATA:',
    '        records.append(make_clean_record(',
    '            slug=item[0], name=item[1], name_ur=item[2], category=item[3], city=item[4], region="Khyber Pakhtunkhwa",',
    '            lat=item[5], lon=item[6], radius=item[7], short_en=item[8], short_ur=item[9], desc_en=item[10], desc_ur=item[11]',
    '        ))',
    '    return records',
    ''
])

with open(dest, "w", encoding="utf-8") as f:
    f.write("\n".join(file_lines))

print(f"Successfully wrote {len(KP_DATA)} landmarks to {dest}!")
